import{_ as n,c as t,o as r,ah as i}from"./chunks/framework.dGCgOE9J.js";const c=JSON.parse('{"title":"25. QGIS-Arbeitsplatz einrichten","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-b-betrieb-admin-qgis/25-qgis-arbeitsplatz-einrichten.md","filePath":"manual/teil-b-betrieb-admin-qgis/25-qgis-arbeitsplatz-einrichten.md"}'),a={name:"manual/teil-b-betrieb-admin-qgis/25-qgis-arbeitsplatz-einrichten.md"};function d(s,e,o,l,u,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="_25-qgis-arbeitsplatz-einrichten" tabindex="-1">25. QGIS-Arbeitsplatz einrichten <a class="header-anchor" href="#_25-qgis-arbeitsplatz-einrichten" aria-label="Permalink to &quot;25. QGIS-Arbeitsplatz einrichten&quot;">​</a></h1><p>Die Geometrie des Netzes – der Verlauf der Trassen, die Lage der Netzknoten und Adressen, der Zuschnitt der Gebiete – wird nicht in der Weboberfläche bearbeitet, sondern in <strong>QGIS</strong>. Dieses Kapitel beschreibt, was ein QGIS-Arbeitsplatz für Qonnectra braucht: die Version, die Verbindung zu den Daten und den Aufbau der Layer. Wie Sie QGIS installieren, bedienen und Layer gestalten, beschreibt die <a href="https://docs.qgis.org/latest/de/docs/user_manual/" target="_blank" rel="noreferrer">Dokumentation von QGIS</a>, auf die dieses Kapitel verweist, statt sie zu wiederholen.</p><h2 id="_25-1-voraussetzungen-und-geprufte-qgis-versionen" tabindex="-1">25.1 Voraussetzungen und geprüfte QGIS-Versionen <a class="header-anchor" href="#_25-1-voraussetzungen-und-geprufte-qgis-versionen" aria-label="Permalink to &quot;25.1 Voraussetzungen und geprüfte QGIS-Versionen&quot;">​</a></h2><p>Qonnectra wird mit QGIS Server 3.44 ausgeliefert. Verwenden Sie am Arbeitsplatz dieselbe Hauptversion, die Langzeitversion 3.44.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Ein QGIS-Projekt, das mit einer neueren Version gespeichert wurde als der des QGIS-Servers, kann Einstellungen enthalten, die der Server nicht kennt. Qonnectra warnt beim Hochladen eines solchen Projekts, sofern die Version des Servers in der Konfiguration hinterlegt ist, siehe Abschnitt <a href="./28-betrieb-der-instanz.html#_28-2-konfiguration-uber-umgebungsvariablen">Konfiguration über Umgebungsvariablen</a>, nimmt es aber in jedem Fall an. Wer Projekte für den Server pflegt, arbeitet deshalb mit derselben Version wie der Server.</p></div><p>Für die Arbeit an den Daten brauchen Sie außerdem:</p><ul><li>ein Konto in Qonnectra für die Dienste des QGIS-Servers,</li><li>für die direkte Verbindung zur Datenbank die Zugangsdaten des Datenbankbenutzers für QGIS und einen VPN-Zugang, die Ihnen der Betrieb Ihrer Installation gibt, siehe Kapitel <a href="./28-betrieb-der-instanz.html">Betrieb der Instanz</a>.</li></ul><h2 id="_25-2-verbindung-zur-postgis-datenbank-und-zu-den-diensten" tabindex="-1">25.2 Verbindung zur PostGIS-Datenbank und zu den Diensten <a class="header-anchor" href="#_25-2-verbindung-zur-postgis-datenbank-und-zu-den-diensten" aria-label="Permalink to &quot;25.2 Verbindung zur PostGIS-Datenbank und zu den Diensten&quot;">​</a></h2><p>Es gibt zwei Wege zu den Daten, für zwei Zwecke.</p><p><strong>Die Dienste des QGIS-Servers</strong> liefern Karten und Objekte zum Ansehen. Sie stehen unter einer eigenen Adresse, die mit <code>qgis.</code> beginnt, und brauchen den Parameter <code>MAP</code> mit dem Namen eines hinterlegten Projekts:</p><p><code>https://qgis.ihre-domain.de/ows/?MAP=/projects/netzdokumentation.qgs</code></p><p>Diese Adresse tragen Sie in QGIS als neue WMS- oder WFS-Verbindung ein. Als Anmeldung verwenden Sie Benutzername und Passwort Ihres Qonnectra-Kontos. Welche Projekte hinterlegt sind und wie ihre Adressen lauten, zeigt der Administrationsbereich, siehe Abschnitt <a href="./27-qgis-server-und-kartendienste.html#_27-1-qgis-projekte-in-qonnectra-hinterlegen">QGIS-Projekte in Qonnectra hinterlegen</a>.</p><p><strong>Die direkte Verbindung zur Datenbank</strong> dient dem Bearbeiten. Die Datenbank ist aus dem Internet nicht erreichbar; der Weg führt über das VPN der Installation (WireGuard). Ist das VPN verbunden, legen Sie in QGIS eine PostgreSQL-Verbindung an:</p><table tabindex="0"><thead><tr><th>Feld</th><th>Wert</th></tr></thead><tbody><tr><td>Host</td><td><code>10.13.13.1</code></td></tr><tr><td>Port</td><td><code>5432</code></td></tr><tr><td>Datenbank</td><td>vom Betrieb genannt</td></tr><tr><td>Benutzername und Passwort</td><td>die des Datenbankbenutzers für QGIS, vom Betrieb genannt</td></tr><tr><td>SSL-Modus</td><td>„deaktivieren“</td></tr></tbody></table><p>Wie eine PostgreSQL-Verbindung in QGIS angelegt wird, beschreibt die QGIS-Dokumentation im Kapitel <a href="https://docs.qgis.org/latest/de/docs/user_manual/managing_data_source/opening_data.html#creating-a-stored-connection" target="_blank" rel="noreferrer">PostGIS-Layer</a>.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Der Datenbankbenutzer für QGIS darf in allen Tabellen lesen, anlegen, ändern und löschen, auch in denen der Benutzerkonten und der Rechte. Die Rollen aus Kapitel <a href="./19-rollen-und-rechte.html">Rollen und Rechte</a> gelten für ihn nicht. Wer diese Zugangsdaten hat, kann jede Trasse jedes Projekts löschen und jedem Konto Administrationsrechte geben – sie kommen einem Administrationszugang gleich. Geben Sie sie nur an Personen, denen Sie auch die Administration der Installation anvertrauen.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Hinterlegte QGIS-Projekte verweisen auf die Datenbank über einen PostgreSQL-Dienst mit dem Namen <code>qonnectra</code>. Wollen Sie ein solches Projekt am Arbeitsplatz öffnen, legen Sie einen gleichnamigen Dienst in der Datei <code>pg_service.conf</code> Ihres Rechners an, mit den Werten der Tabelle oben. Ohne ihn findet QGIS die Layer nicht.</p><p>Umgekehrt muss ein Projekt, das Sie für den QGIS-Server erstellen, seine Layer bereits über diesen Dienst laden und nicht über eine Verbindung mit Host <code>10.13.13.1</code>: Der Server erreicht die Adresse des VPN nicht, und Qonnectra stellt PostgreSQL-Layer beim Hochladen nicht um, siehe Abschnitt <a href="./27-qgis-server-und-kartendienste.html#_27-1-qgis-projekte-in-qonnectra-hinterlegen">QGIS-Projekte in Qonnectra hinterlegen</a>.</p></div><h2 id="_25-3-layer-koordinatenbezugssystem-und-stile" tabindex="-1">25.3 Layer, Koordinatenbezugssystem und Stile <a class="header-anchor" href="#_25-3-layer-koordinatenbezugssystem-und-stile" aria-label="Permalink to &quot;25.3 Layer, Koordinatenbezugssystem und Stile&quot;">​</a></h2><p>Alle Geometrien liegen im Koordinatenbezugssystem der Installation, üblicherweise ETRS89 / UTM Zone 32N (EPSG:25832). Setzen Sie das QGIS-Projekt auf dasselbe System; sonst rechnet QGIS jede Bearbeitung um.</p><p>Diese vier Tabellen enthalten die Geometrie des Netzes und werden als Layer geladen:</p><table tabindex="0"><thead><tr><th>Tabelle</th><th>Geometrie</th><th>Inhalt</th></tr></thead><tbody><tr><td><code>trench</code></td><td>Linie</td><td>Trassen</td></tr><tr><td><code>node</code></td><td>Punkt</td><td>Netzknoten</td></tr><tr><td><code>address</code></td><td>Punkt</td><td>Adressen</td></tr><tr><td><code>area</code></td><td>Fläche</td><td>Gebiete</td></tr></tbody></table><p>Eine Geometrie hat außerdem <code>pipeline_inquiry_area</code>, die Auskunftsbereiche der Leitungsauskunft. Sie werden in der Weboberfläche gezeichnet, siehe Kapitel <a href="./../teil-a-anwenderhandbuch/08-leitungsauskunft.html">Leitungsauskunft</a>.</p><p>Jede Tabelle enthält die Objekte aller Projekte. Setzen Sie am Layer einen Filter auf die Spalte <code>project</code> mit der Nummer Ihres Projekts, siehe Abschnitt <a href="./21-projekte-und-stammdaten.html#_21-1-projekte-anlegen-und-vorbelegungen-setzen">Projekte anlegen</a>; sonst bearbeiten Sie versehentlich ein fremdes Projekt.</p><p>Neben <code>geom</code> hat jede dieser Tabellen eine zweite Geometriespalte, <code>geom_3857</code>. Qonnectra berechnet sie selbst für die Karte der Weboberfläche. Laden Sie die Layer immer mit der Spalte <code>geom</code>; die zweite lässt sich nicht bearbeiten.</p><p>Stammdaten wie Status oder Netzknotentyp stehen in diesen Tabellen als Nummern. Laden Sie die zugehörigen Tabellen – etwa <code>attributes_status</code> oder <code>attributes_node_type</code> – ohne Geometrie dazu und richten Sie im Layer für die Spalte eine Wertbeziehung zu der Tabelle ein; dann zeigt QGIS die Bezeichnungen und bietet sie beim Bearbeiten zur Auswahl. Das beschreibt die QGIS-Dokumentation unter <a href="https://docs.qgis.org/latest/de/docs/user_manual/working_with_vector/vector_properties.html#edit-widgets" target="_blank" rel="noreferrer">Bearbeitungselement Wertbeziehung</a>.</p><p>Einen fertigen Aufbau mit Verbindungen, Filtern und Stilen erhalten Sie am einfachsten aus einem QGIS-Projekt, das Ihre Administration im Administrationsbereich hinterlegt hat: Die Aktion „Mit PostgreSQL-Datenquellen herunterladen“ liefert es zum Öffnen am Arbeitsplatz, siehe Abschnitt <a href="./27-qgis-server-und-kartendienste.html#_27-1-qgis-projekte-in-qonnectra-hinterlegen">QGIS-Projekte in Qonnectra hinterlegen</a>.</p>',26)])])}const g=n(a,[["render",d]]);export{c as __pageData,g as default};
